import sys

def print_cardiogram(n, a):
    x_coords = [0] + list(a.cumsum())
    y_coords = [0]

    for i in range(1, n):
        y_change = -a[i-1] if i % 2 == 1 else a[i-1]
        y_coords.append(y_coords[-1] + y_change)

    max_y = max(abs(y) for y in y_coords)
    width = x_coords[-1]

    cardiogram = [[' ' for _ in range(width + 1)] for _ in range(max_y + 1)]

    for i in range(len(x_coords) - 1):
        x1, x2 = x_coords[i], x_coords[i + 1]
        y1, y2 = y_coords[i], y_coords[i + 1]

        if x1 == x2:
            continue

        if y1 == y2:
            for x in range(min(x1, x2) + 1, max(x1, x2) + 1):
                cardiogram[y1][x] = '-'
        else:
            slope = (y2 - y1) / (x2 - x1)
            for x in range(min(x1, x2) + 1, max(x1, x2) + 1):
                y = y1 + slope * (x - x1)
                rounded_y = round(y)
                cardiogram[rounded_y][x] = '\\' if slope > 0 else '/'

    for row in cardiogram:
        print(''.join(row))

