import sys

def draw_cardiogram(n, sequence):
    x_sum = 0
    y = 0
    points = [(0, 0)]

    for i in range(n):
        x_sum += sequence[i]
        if i % 2 == 0:
            y += sequence[i]
        else:
            y -= sequence[i]
        points.append((x_sum, y))

    x_max = points[-1][0]
    y_min, y_max = min(point[1] for point in points), max(point[1] for point in points)

    canvas = [[' ' for _ in range(x_max + 1)] for _ in range(y_max - y_min + 1)]

    for i in range(len(points) - 1):
        x1, y1 = points[i]
        x2, y2 = points[i + 1]

        if x1 != x2:
            dx = 1 if x2 > x1 else -1
            dy = 1 if y2 > y1 else -1

            if abs(x2 - x1) == abs(y2 - y1):
                for x, y in zip(range(x1, x2 + dx, dx), range(y1, y2 + dy, dy)):
                    canvas[y_max - y][x] = '/' if (i + 1) % 2 == 0 else '\\'
            else:
                x, y = x1, y1
                while x != x2 + dx or y != y2 + dy:
                    canvas[y_max - y][x] = '/' if (i + 1) % 2 == 0 else '\\'
                    x += dx
                    y += dy

    for row in canvas:
        print(''.join(row).rstrip())

