import sys

def draw_cardiogram(n, a):
    x_sum = sum(a)
    y_coords = [sum(a[:i+1]) * (-1)**(i+1) for i in range(n)]
    y_max = max(abs(y) for y in y_coords)

    cardiogram = [[' ' for _ in range(x_sum)] for _ in range(y_max)]

    prev_x, prev_y = 0, 0
    for i in range(n):
        curr_x = sum(a[:i+1])
        curr_y = y_coords[i]

        dx, dy = curr_x - prev_x, curr_y - prev_y
        if dx == 0:
            for y in range(min(prev_y, curr_y), max(prev_y, curr_y)):
                cardiogram[y][prev_x] = '/' if dy > 0 else '\\'
        elif dy == 0:
            for x in range(min(prev_x, curr_x), max(prev_x, curr_x)):
                cardiogram[prev_y][x] = '\\' if dx > 0 else '/'
        else:
            for x, y in zip(range(min(prev_x, curr_x), max(prev_x, curr_x)),
                            range(min(prev_y, curr_y), max(prev_y, curr_y))):
                cardiogram[y][x] = '/' if dx > 0 else '\\'

        prev_x, prev_y = curr_x, curr_y

    for row in cardiogram:
        print(''.join(row))

